  ('src-toyota-2025-tundra', 'towing_guide', 'https://www.toyota.com/content/dam/toyota/brochures/pdf/2025/tundra_towing_guide.pdf', '2025 Toyota Tundra Towing Guide', 'Toyota Motor Sales, U.S.A., Inc.', 2024, '8-11', 'SAE J2807 Towing Ratings', 'source_unavailable', '2024-11-05', 'TowingSpecs Automotive Verification Team', 'Specifications recorded from official 2025 publication (pages 8–11). Direct DAM link is undergoing repair; verified via Toyota Owners portal (https://www.toyota.com/owners/resources/warranty-owners-manuals).'),
  ('src-toyota-2025-tacoma', 'spec_sheet', 'https://pressroom.toyota.com/vehicle/2025-toyota-tacoma/', '2025 Toyota Tacoma Product Specifications', 'Toyota Motor Sales, U.S.A., Inc.', 2024, '6', 'Towing and Payload Ratings', 'manufacturer_verified', '2024-10-25', 'TowingSpecs Automotive Verification Team', 'Official manufacturer product specifications verified from Toyota Pressroom (page 6: Capacities & Towing). All Double Cab i-FORCE 2.4L Turbo 4WD ratings confirmed under SAE J2807.'),
