  ('src-toyota-2024-towing-guide', 'towing_guide', 'https://www.toyota.com/owners/resources/warranty-owners-manuals', '2024 Toyota Towing & Capacity Guide', 'Toyota Motor Sales, U.S.A., Inc.', 2023, '10-32', 'SAE J2807 Towing Ratings', 'partially_verified', '2024-10-20', 'TowingSpecs Automotive Verification Team', 'Official Toyota Towing Guide covering 2024 Tacoma, Tundra, Grand Highlander, Land Cruiser 250, Sequoia, 4Runner, and Sienna.'),
  ('src-toyota-2022-highlander', 'spec_sheet', 'https://pressroom.toyota.com/2022-toyota-highlander-updates-include-new-hybrid-only-bronze-edition/', '2022 Toyota Highlander Product Specifications & eBrochure', 'Toyota Motor Sales, U.S.A., Inc.', 2021, 'Mechanical & Capacities', 'Towing & Payload Specifications', 'partially_verified', '2024-10-15', 'TowingSpecs Automotive Verification Team', 'Press release covers 2022 Highlander Bronze Edition styling package but lacks full mechanical towing capacity tables. Ratings (5,000 lbs 3.5L V6 / 3,500 lbs 2.5L Hybrid under SAE J2807) recorded from owner documentation; demoted to partially_verified pending direct link to complete technical specification sheet.'),
  ('src-toyota-2013-towing-guide', 'towing_guide', 'https://www.toyota.com/owners/resources/warranty-owners-manuals', '2013 Toyota Towing & Capacity Guide', 'Toyota Motor Sales, U.S.A., Inc.', 2012, '12-28', 'Toyota Vehicle Towing Capacity Charts', 'partially_verified', '2024-10-20', 'TowingSpecs Automotive Verification Team', 'Official manufacturer towing publication for 2013 US-market Toyota vehicles. Ratings certified under SAE J2807 standard testing.'),
