  ('src-honda-2024-ridgeline', 'spec_sheet', 'https://hondanews.com/en-US/honda-automobiles/channels/honda-ridgeline?selectedTabId=honda-ridgeline-specs', '2024 Honda Ridgeline Engineering & Towing Specifications', 'American Honda Motor Co., Inc.', 2023, 'Chassis & Towing', 'i-VTM4 AWD System', 'manufacturer_verified', '2024-10-19', 'TowingSpecs Automotive Verification Team', 'All 2024 Ridgeline trims feature standard i-VTM4 AWD and integrated Class III hitch, rated for 5,000 lbs conventional towing.'),
  ('src-jeep-2024-grand-cherokee', 'spec_sheet', 'https://media.stellantisnorthamerica.com/newsrelease.do?id=25123&mid=1', '2024 Jeep Grand Cherokee Technical Specifications', 'FCA US LLC', 2023, 'Weights & Capacities', 'Trailer Tow Ratings', 'partially_verified', '2024-10-20', 'TowingSpecs Automotive Verification Team', 'Official Stellantis media release. 3.6L Pentastar V6 4x4 rated at 6,200 lbs with Trailer Tow Prep Package under SAE J2807.'),
  ('src-jeep-2024-wrangler', 'spec_sheet', 'https://media.stellantisnorthamerica.com/newsrelease.do?id=25120&mid=1', '2024 Jeep Wrangler Specifications & Full-Float Axle Ratings', 'FCA US LLC', 2023, 'Chassis & Towing Matrix', 'Rubicon Dana 44 Full-Float Ratings', 'manufacturer_verified', '2024-10-20', 'TowingSpecs Automotive Verification Team', '2024 refresh introduced first-ever factory full-float Dana 44 HD rear axle on Rubicon, increasing towing rating from 3,500 lbs to 5,000 lbs. Standard 4-door trims remain at 3,500 lbs.'),
