  ('src-ram-2016-towing', 'towing_guide', 'https://www.ramtrucks.com/content/dam/fca-brands/na/ramtrucks/en_us/towing-guide/2016_Ram_1500_Towing_Specs.pdf', '2016 Ram 1500 Towing and Capacity Chart', 'FCA US LLC', 2015, '1-6', 'Crew Cab 4x4 Specifications', 'partially_verified', '2024-10-25', 'TowingSpecs Automotive Verification Team', '5.7L HEMI V8 4WD Crew Cab with 3.92 axle rated at 10,140 lbs. 3.6L Pentastar V6 4WD rated at 4,450 lbs with 3.21 axle.'),
  ('src-ram-2017-towing', 'towing_guide', 'https://www.ramtrucks.com/content/dam/fca-brands/na/ramtrucks/en_us/towing-guide/2017_Ram_1500_Towing_Specs.pdf', '2017 Ram 1500 Towing and Capacity Chart', 'FCA US LLC', 2016, '1-6', 'Crew Cab 4x4 Specifications', 'partially_verified', '2024-10-25', 'TowingSpecs Automotive Verification Team', '5.7L HEMI V8 4WD Crew Cab with 3.92 axle rated at 10,140 lbs; 3.21 axle rated at 8,140 lbs.'),
  ('src-ram-2018-towing', 'towing_guide', 'https://www.ramtrucks.com/content/dam/fca-brands/na/ramtrucks/en_us/towing-guide/2018_Ram_1500_Towing_Specs.pdf', '2018 Ram 1500 Towing and Capacity Chart', 'FCA US LLC', 2017, '1-6', 'Crew Cab 4x4 Specifications', 'partially_verified', '2024-10-25', 'TowingSpecs Automotive Verification Team', 'DS 4th Gen final full year. 5.7L HEMI V8 4WD Crew Cab with 3.92 axle rated at 10,140 lbs. 3.0L EcoDiesel V6 rated at 9,210 lbs with 3.92 axle.'),
  ('src-ram-2019-towing', 'towing_guide', 'https://www.ramtrucks.com/content/dam/fca-brands/na/ramtrucks/en_us/towing-guide/2019_Ram_1500_Towing_Specs.pdf', '2019 Ram 1500 Trailer Towing & Capacity Guide', 'FCA US LLC', 2018, '1-8', 'All-New Ram 1500 (DT) Ratings', 'partially_verified', '2024-10-25', 'TowingSpecs Automotive Verification Team', 'All-new DT 5th Gen launch. 5.7L HEMI V8 eTorque 4WD Crew Cab 5''7" bed with 3.92 axle and Max Tow Package rated at 11,290 lbs. Non-eTorque with 3.21 axle rated at 8,280 lbs.'),
  ('src-ram-2020-towing', 'towing_guide', 'https://www.ramtrucks.com/content/dam/fca-brands/na/ramtrucks/en_us/towing-guide/2020_Ram_1500_Towing_Specs.pdf', '2020 Ram 1500 Towing and Payload Ratings', 'FCA US LLC', 2019, '1-8', 'DT 1500 Towing & Payload Matrix', 'partially_verified', '2024-10-25', 'TowingSpecs Automotive Verification Team', '5.7L HEMI V8 eTorque 4WD Crew Cab with 3.92 axle rated at 11,290 lbs. Gen 3 3.0L EcoDiesel V6 rated at 9,860 lbs with 3.92 axle.'),
  ('src-toyota-2014-towing', 'towing_guide', 'https://www.toyota.com/content/dam/toyota/brochures/pdf/2014/toyota_towing_guide.pdf', '2014 Toyota Towing & Capacity Specifications', 'Toyota Motor Sales, U.S.A., Inc.', 2013, '4-12', 'SAE J2807 Certified Ratings (Tacoma, Tundra, 4Runner, Highlander)', 'partially_verified', '2024-10-25', 'TowingSpecs Automotive Verification Team', 'Certified under SAE J2807 standards. Tacoma V6 Tow Pkg: 6,400 lbs (3,500 lbs standard). Tundra 5.7L V8 4WD CrewMax: 9,000 lbs (10,200 lbs 2WD Double Cab). 4Runner SR5 4WD: 4,700 lbs. Highlander V6 AWD Tow Prep: 5,000 lbs (1,500 lbs 4-cyl standard).'),
  ('src-toyota-2015-towing', 'towing_guide', 'https://www.toyota.com/content/dam/toyota/brochures/pdf/2015/toyota_towing_guide.pdf', '2015 Toyota Towing & Capacity Specifications', 'Toyota Motor Sales, U.S.A., Inc.', 2014, '4-12', 'SAE J2807 Certified Ratings (Tacoma, Tundra)', 'partially_verified', '2024-10-25', 'TowingSpecs Automotive Verification Team', 'Certified under SAE J2807 standards. Tacoma V6 Double Cab 4x4 Tow Pkg: 6,400 lbs (3,500 lbs 4-cyl). Tundra CrewMax 5.7L V8 4x4: 9,000 lbs.'),
  ('src-toyota-2016-towing', 'towing_guide', 'https://www.toyota.com/content/dam/toyota/brochures/pdf/2016/toyota_towing_guide.pdf', '2016 Toyota Towing & Capacity Specifications', 'Toyota Motor Sales, U.S.A., Inc.', 2015, '4-15', 'SAE J2807 Certified Ratings (Tacoma 3rd Gen, Tundra, 4Runner, Highlander)', 'partially_verified', '2024-10-25', 'TowingSpecs Automotive Verification Team', '3rd Gen Tacoma launch (3.5L V6 Tow Pkg: 6,400 lbs). Tundra 5.7L V8 CrewMax: 9,000 lbs (Double Cab 4WD: 9,900 lbs). 4Runner 4.0L V6 4WD: 5,000 lbs. Highlander V6 AWD Tow Prep: 5,000 lbs.'),
  ('src-toyota-2017-towing', 'towing_guide', 'https://www.toyota.com/content/dam/toyota/brochures/pdf/2017/toyota_towing_guide.pdf', '2017 Toyota Towing & Capacity Specifications', 'Toyota Motor Sales, U.S.A., Inc.', 2016, '4-12', 'SAE J2807 Certified Ratings (Tacoma, Tundra)', 'partially_verified', '2024-10-25', 'TowingSpecs Automotive Verification Team', 'Certified under SAE J2807 standards. Tacoma TRD Off-Road V6 4x4 Tow Pkg: 6,400 lbs (3,500 lbs 4-cyl). Tundra SR5 CrewMax 5.7L V8 4x4: 9,000 lbs.'),
  ('src-toyota-2018-towing', 'towing_guide', 'https://www.toyota.com/content/dam/toyota/brochures/pdf/2018/toyota_towing_guide.pdf', '2018 Toyota Towing & Capacity Specifications', 'Toyota Motor Sales, U.S.A., Inc.', 2017, '4-14', 'SAE J2807 Certified Ratings (Tacoma, Tundra, 4Runner, Highlander)', 'partially_verified', '2024-10-25', 'TowingSpecs Automotive Verification Team', 'Tacoma TRD Off-Road V6 Tow Pkg: 6,400 lbs. Tundra CrewMax 5.7L V8 4x4: 9,200 lbs. 4Runner TRD Off-Road 4WD: 5,000 lbs. Highlander 3.5L V6 AWD Tow Prep: 5,000 lbs (Hybrid AWD: 3,500 lbs).'),
  ('src-toyota-2019-towing', 'towing_guide', 'https://www.toyota.com/content/dam/toyota/brochures/pdf/2019/toyota_towing_guide.pdf', '2019 Toyota Towing & Capacity Specifications', 'Toyota Motor Sales, U.S.A., Inc.', 2018, '4-12', 'SAE J2807 Certified Ratings (Tacoma, Tundra)', 'partially_verified', '2024-10-25', 'TowingSpecs Automotive Verification Team', 'Tacoma TRD Off-Road 3.5L V6 4x4 Tow Pkg: 6,400 lbs. Tundra CrewMax 5.7L V8 4x4: 9,200 lbs (Double Cab 2WD: 10,200 lbs).'),
  ('src-toyota-2020-towing', 'towing_guide', 'https://www.toyota.com/content/dam/toyota/brochures/pdf/2020/toyota_towing_guide.pdf', '2020 Toyota Towing & Capacity Specifications', 'Toyota Motor Sales, U.S.A., Inc.', 2019, '4-16', 'SAE J2807 Certified Ratings (Tacoma, Tundra, 4Runner, Highlander 4th Gen)', 'partially_verified', '2024-10-25', 'TowingSpecs Automotive Verification Team', 'Tacoma TRD Off-Road V6: 6,400 lbs. Tundra CrewMax 5.7L V8 4x4: 9,200 lbs (Double Cab 4x4: 9,800 lbs). 4Runner SR5 4WD: 5,000 lbs. 4th Gen Highlander 3.5L V6 AWD standard cooling: 5,000 lbs (Hybrid AWD: 3,500 lbs).'),
  ('src-honda-2016-pilot', 'spec_sheet', 'https://hondanews.com/en-US/releases/2016-honda-pilot-specifications-and-features', '2016 Honda Pilot Specifications & Towing Ratings', 'American Honda Motor Co., Inc.', 2015, '2-5', 'AWD & 2WD Towing Matrices', 'manufacturer_verified', '2024-10-25', 'TowingSpecs Automotive Verification Team', '3rd Gen Pilot launch. AWD models equipped with accessory ATF cooler and Class III hitch receiver rated at 5,000 lbs conventional towing under SAE J2807. 2WD models rated at 3,500 lbs.'),
  ('src-honda-2019-pilot', 'spec_sheet', 'https://hondanews.com/en-US/releases/2019-honda-pilot-specifications-features', '2019 Honda Pilot Specifications & Features', 'American Honda Motor Co., Inc.', 2018, '2-6', 'Towing Capacities & Mechanical Specs', 'manufacturer_verified', '2024-10-25', 'TowingSpecs Automotive Verification Team', 'AWD models with factory/accessory transmission cooler rated at 5,000 lbs. 2WD models rated at 3,500 lbs under SAE J2807.'),
  ('src-nissan-2016-frontier', 'towing_guide', 'https://www.nissanusa.com/content/dam/Nissan/us/manuals_guides/Frontier/2016/2016-nissan-frontier-towing-guide.pdf', '2016 Nissan Frontier Towing Guide', 'Nissan North America, Inc.', 2015, '4-8', 'Crew Cab & King Cab Ratings', 'partially_verified', '2024-10-25', 'TowingSpecs Automotive Verification Team', '4.0L DOHC V6 VQ40DE 5-speed automatic. PRO-4X Crew Cab 4x4 rated at 6,100 lbs with factory hitch receiver. SV King Cab 4x2 rated at 6,500 lbs.'),
  ('src-nissan-2019-frontier', 'towing_guide', 'https://www.nissanusa.com/content/dam/Nissan/us/manuals_guides/Frontier/2019/2019-nissan-frontier-towing-guide.pdf', '2019 Nissan Frontier Towing Guide', 'Nissan North America, Inc.', 2018, '4-8', 'Crew Cab & King Cab Ratings', 'partially_verified', '2024-10-25', 'TowingSpecs Automotive Verification Team', '4.0L DOHC V6 VQ40DE 5-speed automatic. PRO-4X Crew Cab 4x4 rated at 6,100 lbs with factory hitch receiver. SV King Cab 4x2 rated at 6,500 lbs.'),
