  ('src-chevy-2010-trailering', 'towing_guide', 'https://www.chevrolet.com/content/dam/chevrolet/na/us/english/index/vehicle-groups/trailering-and-towing/trucks/02-pdf/2010-chevrolet-trailering-guide.pdf', '2010 Chevrolet Trailering Guide', 'General Motors LLC', 2009, '8-18', 'Silverado 1500 & Tahoe Conventional Trailering', 'partially_verified', '2024-10-28', 'TowingSpecs Automotive Verification Team', 'GMT900 platform. Silverado 1500 Crew Cab 4WD with NHT Max Trailering Package (6.2L V8 Vortec, 3.73 axle, heavy-duty cooling) rated at 10,400 lbs. 5.3L V8 with Z82 standard trailering (3.42 axle) rated at 9,600 lbs. Tahoe 5.3L 4WD with NHT Max Trailering (3.42 axle) rated at 8,200 lbs (standard 3.08 axle at 5,200 lbs).'),
  ('src-ram-2010-towing', 'towing_guide', 'https://www.ramtrucks.com/en/towing_guide/pdf/2010-RAM.1500.Towing.Specs.pdf', '2010 Ram 1500 Specifications & Towing Guide', 'Chrysler Group LLC', 2009, '2-6', 'Ram 1500 Conventional Towing Matrix', 'partially_verified', '2024-10-28', 'TowingSpecs Automotive Verification Team', 'Dodge Ram 1500 4th Gen. 5.7L HEMI V8 (390 hp) Crew Cab 4WD with 3.92 axle and Class IV hitch rated at 10,050 lbs. Standard 3.55 axle rated at 8,500 lbs.'),
  ('src-toyota-2010-specs', 'spec_sheet', 'https://pressroom.toyota.com/vehicle/2010-toyota-tundra-specs/', '2010 Toyota Towing & Capacity Specifications', 'Toyota Motor Sales, U.S.A., Inc.', 2009, '6-18', 'Tacoma & Tundra Towing Guide', 'partially_verified', '2024-10-28', 'TowingSpecs Automotive Verification Team', 'Pre-SAE J2807 rating. Tundra CrewMax 5.7L V8 4x4 with Tow Package (4.30 axle) rated at 10,100 lbs (Double Cab 4x2 at 10,800 lbs). Tacoma Double Cab 4WD 4.0L V6 with factory V6 Tow Package rated at 6,500 lbs (Access Cab 2.7L I4 at 3,500 lbs).'),
  ('src-ford-2011-rv-guide', 'towing_guide', 'https://www.fleet.ford.com/content/dam/aem_fleet/en_us/fleet/towing-guides/2011_Ford_RV_Trailer_Towing_Guide.pdf', '2011 Ford RV & Trailer Towing Guide', 'Ford Motor Company', 2010, '14-22', 'F-150 & Explorer Conventional Towing', 'partially_verified', '2024-10-28', 'TowingSpecs Automotive Verification Team', 'Launch of 3.5L EcoBoost and 5.0L Coyote V8. F-150 SuperCrew 4WD 3.5L with Max Trailer Tow Package (53C, 3.73 axle) rated at 11,300 lbs. 5.0L V8 4WD with standard tow package (3.55 axle) rated at 7,700 lbs. Explorer 3.5L V6 AWD with Class III Trailer Tow Package rated at 5,000 lbs.'),
  ('src-chevy-2011-trailering', 'towing_guide', 'https://www.chevrolet.com/content/dam/chevrolet/na/us/english/index/vehicle-groups/trailering-and-towing/trucks/02-pdf/2011-chevrolet-trailering-guide.pdf', '2011 Chevrolet Trailering Guide', 'General Motors LLC', 2010, '8-18', 'Silverado 1500 & Tahoe Conventional Trailering', 'partially_verified', '2024-10-28', 'TowingSpecs Automotive Verification Team', 'Silverado 1500 Crew Cab 4WD with NHT Max Trailering (6.2L V8, 3.73 axle) rated at 10,600 lbs. 5.3L V8 with Z82 (3.42 axle) rated at 9,600 lbs. Tahoe 5.3L 4WD with NHT (3.42 axle) rated at 8,200 lbs (standard 3.08 axle at 5,200 lbs).'),
  ('src-ram-2011-towing', 'towing_guide', 'https://www.ramtrucks.com/en/towing_guide/pdf/2011-RAM.1500.Towing.Specs.pdf', '2011 Ram 1500 Towing Specifications & Capability Chart', 'Chrysler Group LLC', 2010, '2-6', 'Ram 1500 Conventional Towing Matrix', 'partially_verified', '2024-10-28', 'TowingSpecs Automotive Verification Team', 'Official Ram Trucks specification. 5.7L HEMI V8 (390 hp) Crew Cab 4WD with 3.92 axle rated at 10,250 lbs. With 3.55 axle rated at 8,500 lbs.'),
  ('src-toyota-2011-specs', 'spec_sheet', 'https://pressroom.toyota.com/vehicle/2011-toyota-tundra-specs/', '2011 Toyota Towing & Capacity Specifications (SAE J2807 Certified)', 'Toyota Motor Sales, U.S.A., Inc.', 2010, '4-16', 'SAE J2807 Certified Ratings: Tacoma, Tundra, 4Runner', 'partially_verified', '2024-10-28', 'TowingSpecs Automotive Verification Team', 'First year of official SAE J2807 standard certification. Tundra CrewMax 5.7L V8 4x4 certified at 9,000 lbs (Double Cab 4x2 at 10,400 lbs). Tacoma Double Cab 4WD 4.0L V6 with V6 Tow Package certified at 6,500 lbs. 4Runner SR5 4WD 4.0L V6 certified at 5,000 lbs.'),
  ('src-ford-2012-rv-guide', 'towing_guide', 'https://www.fleet.ford.com/content/dam/aem_fleet/en_us/fleet/towing-guides/2012_Ford_RV_Trailer_Towing_Guide.pdf', '2012 Ford RV & Trailer Towing Guide', 'Ford Motor Company', 2011, '16-22', 'F-150 Conventional Towing', 'partially_verified', '2024-10-28', 'TowingSpecs Automotive Verification Team', 'F-150 SuperCrew 4WD 3.5L EcoBoost with Max Trailer Tow Package (53C, 3.73 axle) rated at 11,300 lbs. 5.0L V8 4WD with standard tow package (3.55 axle) rated at 7,700 lbs.'),
  ('src-chevy-2012-trailering', 'towing_guide', 'https://www.chevrolet.com/content/dam/chevrolet/na/us/english/index/vehicle-groups/trailering-and-towing/trucks/02-pdf/2012-chevrolet-trailering-guide.pdf', '2012 Chevrolet Trailering Guide', 'General Motors LLC', 2011, '10-18', 'Silverado 1500 Conventional Trailering', 'partially_verified', '2024-10-28', 'TowingSpecs Automotive Verification Team', 'Silverado 1500 Crew Cab 4WD with NHT Max Trailering (6.2L V8, 3.73 axle) rated at 10,600 lbs. 5.3L V8 with Z82 (3.42 axle) rated at 9,600 lbs.'),
  ('src-gmc-2012-trailering', 'towing_guide', 'https://www.gmc.com/content/dam/gmc/na/us/english/index/vehicle-groups/trailering-and-towing/02-pdf/2012-gmc-trailering-guide.pdf', '2012 GMC Trailering Guide', 'General Motors LLC', 2011, '8-16', 'Sierra 1500 Conventional Trailering', 'partially_verified', '2024-10-28', 'TowingSpecs Automotive Verification Team', 'Sierra 1500 Denali Crew Cab AWD NHT (6.2L V8, 3.73 axle) rated at 10,600 lbs.'),
  ('src-ram-2012-towing', 'towing_guide', 'https://www.ramtrucks.com/en/towing_guide/pdf/2012-RAM.1500.Towing.Specs.pdf', '2012 Ram 1500 Towing Specifications & Matrix', 'Chrysler Group LLC', 2011, '2-6', 'Ram 1500 Conventional Towing Matrix', 'partially_verified', '2024-10-28', 'TowingSpecs Automotive Verification Team', '5.7L HEMI V8 (390 hp) Crew Cab 4WD with 3.92 axle rated at 10,250 lbs. With 3.55 axle rated at 8,500 lbs.'),
