  ('src-ford-2023-rv-guide', 'towing_guide', 'https://www.fleet.ford.com/content/dam/aem_fleet/en_us/fleet/towing-guides/2023_Ford_RV_Trailer_Towing_Guide.pdf', '2023 Ford RV & Trailer Towing Guide', 'Ford Motor Company', 2022, '20-27', 'F-150 & Explorer Conventional Towing', 'partially_verified', '2024-10-28', 'TowingSpecs Automotive Verification Team', 'F-150 SuperCrew 4WD 3.5L EcoBoost with Max Trailer Tow Package (53C, 3.55 locking rear axle) rated at 13,800 lbs. 3.5L PowerBoost Full Hybrid 4WD rated at 12,400 lbs. 5.0L V8 4WD rated at 12,900 lbs. Explorer ST 3.0L EcoBoost AWD with Class IV Tow Package rated at 5,600 lbs.'),
  ('src-chevy-2023-trailering', 'towing_guide', 'https://www.chevrolet.com/content/dam/chevrolet/na/us/english/index/vehicle-groups/trailering-and-towing/trucks/02-pdf/2023-chevrolet-trailering-guide.pdf', '2023 Chevrolet Trailering Guide', 'General Motors LLC', 2022, '14-29', 'Silverado 1500 & Tahoe Trailering Specifications', 'partially_verified', '2024-10-28', 'TowingSpecs Automotive Verification Team', 'Refreshed interior/chassis. Silverado 1500 Crew Cab Short Bed 4WD with NHT Max Trailering (6.2L V8, 3.23 axle, 9.76 axle) rated at 13,200 lbs. 5.3L V8 4WD standard trailering rated at 9,200 lbs. Tahoe 5.3L 4WD with NHT Max Trailering (3.23 axle) rated at 8,200 lbs.'),
  ('src-gmc-2023-trailering', 'towing_guide', 'https://www.gmc.com/content/dam/gmc/na/us/english/index/vehicle-groups/trailering-and-towing/02-pdf/2023-gmc-trailering-guide.pdf', '2023 GMC Trailering Guide', 'General Motors LLC', 2022, '12-24', 'Sierra 1500 Conventional Trailering', 'partially_verified', '2024-10-28', 'TowingSpecs Automotive Verification Team', 'Sierra 1500 Denali Ultimate Crew Cab 4WD with NHT (6.2L V8) rated at 13,000 lbs. SLT 5.3L 4WD rated at 9,200 lbs.'),
  ('src-ram-2023-towing', 'towing_guide', 'https://www.ramtrucks.com/content/dam/fca-brands/na/ramtrucks/en_us/towing-guide/2023_RAM_1500_Towing_Specs.pdf', '2023 Ram 1500 Towing Specifications & Matrix', 'FCA US LLC / Stellantis', 2022, '4-12', 'Ram 1500 Conventional Towing Matrix', 'partially_verified', '2024-10-28', 'TowingSpecs Automotive Verification Team', '5.7L HEMI eTorque Crew Cab 4WD with 3.92 axle and Class IV receiver rated at 11,320 lbs. With 3.21 highway axle rated at 8,320 lbs.'),
  ('src-toyota-2023-specs', 'spec_sheet', 'https://pressroom.toyota.com/vehicle/2023-toyota-tundra-specs/', '2023 Toyota Towing & Capacity Specifications (SAE J2807 Certified)', 'Toyota Motor Sales, U.S.A., Inc.', 2022, '6-22', 'Tundra, Sequoia, Tacoma, 4Runner SAE J2807 Certified Ratings', 'partially_verified', '2024-10-28', 'TowingSpecs Automotive Verification Team', '3rd Gen Tundra 3.4L Twin-Turbo V6 CrewMax 4x4 (5.5'' bed) rated at 11,170 lbs (Double Cab 4x2 at 12,000 lbs). Tundra i-FORCE MAX Hybrid CrewMax 4x4 rated at 11,170 lbs. All-new 3rd Gen Sequoia TNGA-F truck platform with standard i-FORCE MAX Hybrid rated at 9,520 lbs (2WD SR5) and 9,010 lbs (4WD Platinum). Tacoma TRD Off-Road V6 with Tow Package rated at 6,400 lbs. 4Runner SR5 4WD rated at 5,000 lbs.'),
  ('src-honda-2023-pilot', 'spec_sheet', 'https://hondanews.com/en-US/releases/2023-honda-pilot-specifications-features', '2023 Honda Pilot Specifications & Towing Ratings', 'American Honda Motor Co., Inc.', 2022, '2-6', 'Towing & Mechanical Specifications', 'manufacturer_verified', '2024-10-28', 'TowingSpecs Automotive Verification Team', 'All-new 4th generation Pilot. TrailSport and Elite AWD equipped with standard integrated Class III hitch and heavy-duty cooling rated at 5,000 lbs under SAE J2807. 2WD models rated at 3,500 lbs.'),
  ('src-nissan-2023-frontier', 'towing_guide', 'https://www.nissanusa.com/content/dam/Nissan/us/manuals_guides/Frontier/2023/2023-nissan-frontier-towing-guide.pdf', '2023 Nissan Frontier Towing Guide', 'Nissan North America, Inc.', 2022, '4-10', 'Crew Cab & King Cab Towing Ratings', 'partially_verified', '2024-10-28', 'TowingSpecs Automotive Verification Team', '3.8L DOHC V6 with 9-speed automatic. SV King Cab 4x2 rated at 6,720 lbs. PRO-4X Crew Cab 4x4 with factory receiver hitch rated at 6,270 lbs.')
