-- TowingSpecs — Production Seed Data
-- Version: 0002 Expanded (Includes 2013, 2024, 2025 verified manufacturer records)
-- Toyota models certified under SAE J2807 standard testing

-- ─── Data Sources ─────────────────────────────────────────────────────────────
ON CONFLICT (id) DO UPDATE SET verification_status = EXCLUDED.verification_status, updated_at = NOW();

-- ─── Makes ────────────────────────────────────────────────────────────────────
ON CONFLICT (slug) DO NOTHING;

-- ─── Models ───────────────────────────────────────────────────────────────────
ON CONFLICT (make_id, slug) DO NOTHING;

-- ─── Model Years ─────────────────────────────────────────────────────────────
ON CONFLICT (model_id, year) DO NOTHING;

-- ─── Trims ───────────────────────────────────────────────────────────────────
ON CONFLICT (model_year_id, slug) DO NOTHING;

-- ─── Vehicle Configurations ───────────────────────────────────────────────────
ON CONFLICT (id) DO NOTHING;

-- ─── Towing Specs ─────────────────────────────────────────────────────────────
ON CONFLICT (configuration_id) DO NOTHING;

-- ─── Spec Source Links ─────────────────────────────────────────────────────
ON CONFLICT (spec_id, source_id) DO NOTHING;
